Sure! I’ll extract command logic into separate functions to improve modularity. Here’s what I’ll do:

1. Create command functions for each command type (e.g., list, add, remove).
2. Use a mapping object to map command strings to these functions.

Here’s the updated code:

```javascript
// src/cli/commandHandler.js
const { listCommand, addCommand, removeCommand } = require('./utils');

const commands = {
  list: listCommand,
  add: addCommand,
  remove: removeCommand,
};

function handleCommand(command, args) {
  const execute = commands[command];
  if (execute) {
    return execute(args);
  }
  throw new Error(`Unknown command: ${command}`);
}

module.exports = { handleCommand };  
```

Now, I will also update utils.js to define these command functions.

```javascript
// src/cli/utils.js
function listCommand(args) {
  console.log('Listing items...', args);
}

function addCommand(args) {
  console.log('Adding item...', args);
}

function removeCommand(args) {
  console.log('Removing item...', args);
}
}

module.exports = { listCommand, addCommand, removeCommand };
```

